-- Two shared staff accounts replace the per-person ones.
--
-- The team asked for one viewer login and one editor login, with the password
-- being the only thing anybody types. Supabase auth still backs this, and has
-- to: the policies in 0002 grant reads to `authenticated` and edits to whoever
-- private.staff says is an editor, so a real identity must exist. What changed
-- is the account model, not the authorization model.
--
-- The account ids are generated by Supabase, so this looks them up by email
-- instead of hard-coding them. It refuses to run unless both exist, because
-- the delete below would otherwise wipe every staff row and lock the panel for
-- everyone — a failure that would only show up when somebody next tried to
-- sign in.
--
-- Run this AFTER creating both users in Authentication -> Users. The passwords
-- are given out separately and are deliberately not recorded in this file.

begin;

do $$
declare
    viewer_id uuid;
    editor_id uuid;
begin
    select id into viewer_id from auth.users where email = 'viewer@ykmun.org';
    select id into editor_id from auth.users where email = 'editor@ykmun.org';

    if viewer_id is null or editor_id is null then
        raise exception
            'create viewer@ykmun.org and editor@ykmun.org first (Authentication -> Users)';
    end if;

    -- Removes the earlier per-person rows, including the test account. Any
    -- account left in auth.users without a row here can still sign in, but the
    -- policies return nothing for it, so it sees no data.
    delete from private.staff;

    insert into private.staff (user_id, role) values (viewer_id, 'viewer');
    insert into private.staff (user_id, role) values (editor_id, 'editor');
end
$$;

commit;

-- Expected result: exactly two rows.
--
--   select u.email, s.role
--   from private.staff s
--   join auth.users u on u.id = s.user_id
--   order by s.role;
--
--   editor@ykmun.org  | editor
--   viewer@ykmun.org  | viewer
